/**
 * Lark **post** mode (`msg_type: 'post'`) — the non-interactive rendering of an element tree.
 *
 * Shape of the output. One platform message is a post body: `{ zh_cn: { title?, content: [[node, …], …] } }` where
 * every `content` row is one paragraph. The mode emits three kinds of rows:
 * - `md` — a `md` node for every text block (paragraph, heading, list, quote, code fence, table). Feishu post-md is
 *   CommonMark + GFM, so one node carries the whole dialect the platform can express; the text itself is escaped by
 *   {@link escapePostMd} and the *structure* is generated by the handlers (markers, fence delimiters, table rows).
 * - `img` — its own paragraph, because the platform requires an image to be the only node of its paragraph. An image
 *   that stands inside a paragraph is hoisted here by `assemble` and reported as `moved`.
 * - `hr` — the native divider node.
 * `audio` / `video` / `file` split the logical message: each becomes its own platform message in tree order
 * (`message.split`), as the platform has no attachment node inside a post.
 *
 * Purity. `transform` is synchronous and never uploads: every media element becomes a `ResourceRef` placeholder inside
 * the draft, `prepare` resolves it and `serialize` reads the key from `Prepared.resolved`. That is what makes a
 * streamed post cheap — the edit driver re-runs transform/prepare/serialize on every tick against a warm cache.
 *
 * Media decisions taken here (the prepare stage owns `file_type` and the bytes):
 * - `audio` is only playable as OPUS and `video` only as MP4, so any other source is published as a `file` message
 *   (no transcoding) and reported in `RenderReport.moved` (`not-opus` / `not-mp4`).
 * - `code` blocks are emitted as md fences rather than as the native `code_block` node: the node's `language` field
 *   is a closed enum of ~200 uppercase tokens, while a fence keeps the (arbitrary) language of a model-written block
 *   and is highlighted the same way.
 *
 * What the mode renders natively is what its registry holds: a root `<title>` goes to `assemble` as the post title
 * (`envelope('title')`), `at.all` is declared only when the configuration allows it — a group that forbids @all
 * rejects the whole send, so `createPostMode({ allowAtAll: false })` leaves the variant undeclared and the mention
 * falls back to `@所有人` text.
 */

import type { Align, Element } from '@deepseek-ai/satori-element'
import {
  defineMode, ElementRegistry, type Envelope, type LimitViolation, type Mode, type ModeTypes,
  type Prepared, type RenderContext, type ResourceRef, type SerializeContext,
} from '@deepseek-ai/cordis-plugin-im-core'
import { codeSpan, escapeLinkHref, escapePostMd, fenceBlock, mentionMarkdown } from './shared.ts'

// ---------------------------------------------------------------------------------------------------------------
// Types

/** An inline run of one paragraph: user text (escaped), generated markdown, or an image reference. */
export type PostInline =
  | { kind: 'text'; text: string }
  | { kind: 'raw'; text: string }
  | { kind: 'inline-image'; ref: ResourceRef; alt?: string; path?: string }

/** One line of a md block: a prefix (list marker, quote marker, indent) followed by its inline runs. */
export interface PostLine {
  prefix: string
  inlines: PostInline[]
}

/** A block that becomes one `md` node (a paragraph, or several lines of one list / quote / table / fence). */
export interface PostMdNode { kind: 'md'; lines: PostLine[] }
/** An image that becomes its own paragraph (`{ tag: 'img' }`). */
export interface PostImageNode { kind: 'image'; ref: ResourceRef; alt?: string; path?: string }
/** The native divider node. */
export interface PostHrNode { kind: 'hr' }
/** A media element: splits the logical message into its own platform message. */
export interface PostMediaNode {
  kind: 'media'
  /** `msg_type` it is published as: `audio` (OPUS), `media` (video, MP4) or `file`. */
  msgType: 'audio' | 'media' | 'file'
  ref: ResourceRef
  name?: string
  path?: string
}
/** One list item, consumed by the `ul` / `ol` handler that adds its marker. */
export interface PostLiNode { kind: 'li'; lines: PostLine[]; checked?: boolean }
/** One table cell, consumed by the `table` handler. */
export interface PostCellNode { kind: 'cell'; header: boolean; align?: Align; inlines: PostInline[] }
/** One table row, consumed by the `table` handler. */
export interface PostRowNode { kind: 'row'; cells: PostCellNode[] }

/** Anything a handler may return; `assemble` narrows to the block-level members. */
export type PostNode = PostMdNode | PostImageNode | PostHrNode | PostMediaNode | PostLiNode | PostCellNode | PostRowNode
  | PostInline

/** Block-level node of an assembled draft. */
export type PostParagraph = PostMdNode | PostImageNode | PostHrNode

/** One post message before resource resolution. */
export interface PostTextDraft {
  kind: 'post'
  /** Post `title` (a plain string, not markdown). */
  title?: string
  paragraphs: PostParagraph[]
}

/** One media message (audio / video / file) before resource resolution. */
export interface PostMediaDraft {
  kind: 'media'
  msgType: 'audio' | 'media' | 'file'
  ref: ResourceRef
  name?: string
}

export type PostDraft = PostTextDraft | PostMediaDraft

/**
 * Exact request body of one platform message, without the `content` string encoding.
 *
 * `content` is the platform's content **object** (`{ zh_cn: { title?, content: rows } }` for a post, `{ file_key }`
 * for a media message) rather than the JSON string the API wants, so that `RenderReport`/goldens/e2e comparisons see
 * the real strings instead of escaped JSON. {@link postRequestBody} turns it into the exact body to post — the
 * adapter's `sendPayload` / `editPayload` must go through it (or `JSON.stringify(payload.content)` themselves).
 */
export interface PostPayload {
  msg_type: 'post' | 'audio' | 'media' | 'file'
  content: Record<string, unknown>
}

/** The wire body of a payload: `content` as the JSON string Lark expects. */
export function postRequestBody(payload: PostPayload): { msg_type: PostPayload['msg_type'], content: string } {
  return { msg_type: payload.msg_type, content: JSON.stringify(payload.content) }
}

/** The mode types: `node` is what handlers return, `draft` one platform message, `payload` its request body. */
export interface PostTypes extends ModeTypes {
  node: PostNode
  draft: PostDraft
  payload: PostPayload
}

/** Configuration of the post mode; `LarkBot.createModes()` passes it from the adapter config. */
export interface PostModeConfig {
  /**
   * `LarkConfig.allowAtAll`: `false` leaves the `all` variant of `<at>` undeclared, so an @all mention is rendered as
   * `@所有人` text instead of a platform mention; `true`/absent declares it.
   */
  allowAtAll?: boolean
  /** Locale key of the post body; the platform requires at least one. Default `zh_cn`. */
  locale?: string
  /** `limit.update.count` (the platform accepts at most 20 edits per message). */
  updateLimit?: number
  /** `limit.payload.bytes` (the platform rejects a post body above 30 KB). */
  payloadBytes?: number
}

// ---------------------------------------------------------------------------------------------------------------
// Constants

/** `limit.payload.bytes` of a post request. */
export const POST_PAYLOAD_BYTES = 30_000
/** `limit.update.count` of a post message; one edit is reserved for the stream close. */
export const POST_UPDATE_LIMIT = 20
/** Alt text of an image without one (the platform shows it as the hover text). */
const DEFAULT_IMAGE_ALT = '图片'

// ---------------------------------------------------------------------------------------------------------------
// Inline helpers

const text = (value: string): PostInline => ({ kind: 'text', text: escapePostMd(value) })
const raw = (value: string): PostInline => ({ kind: 'raw', text: value })
const blankLine = (): PostLine => ({ prefix: '', inlines: [] })
const cloneLine = (line: PostLine): PostLine => ({ prefix: line.prefix, inlines: [...line.inlines] })

function isInline(node: PostNode): node is PostInline {
  return node.kind === 'text' || node.kind === 'raw' || node.kind === 'inline-image'
}

/** Inline runs of `lines`, blocks separated by a space (cell and label flattening). */
function lineInlines(lines: readonly PostLine[]): PostInline[] {
  const out: PostInline[] = []
  lines.forEach((line, index) => {
    if (index) out.push(raw(' '))
    out.push(...line.inlines)
  })
  return out
}

/**
 * Flatten any node into inline runs: nested blocks are joined with a space, a media element becomes a link to its
 * source (a nested attachment cannot be split out of a list item or a table cell).
 */
function inlinesOf(nodes: readonly PostNode[]): PostInline[] {
  const out: PostInline[] = []
  for (const node of nodes) {
    if (isInline(node)) {
      out.push(node)
      continue
    }
    switch (node.kind) {
      case 'md': out.push(...lineInlines(node.lines)); break
      case 'image': out.push({
        kind: 'inline-image',
        ref: node.ref,
        ...node.alt ? { alt: node.alt } : {},
        ...node.path ? { path: node.path } : {},
      }); break
      case 'media': out.push(raw(mediaLink(node))); break
      case 'li': out.push(...lineInlines(node.lines)); break
      case 'cell': out.push(...node.inlines); break
      case 'row': out.push(...node.cells.flatMap(cell => cell.inlines)); break
      case 'hr': break
    }
  }
  return out
}

/** Display text of inline runs, used where markdown syntax is not allowed (link labels, table cells). */
function inlineLabel(inlines: readonly PostInline[]): string {
  return inlines.map(node => node.kind === 'inline-image' ? imageAlt(node.alt) : node.text).join('')
}

function imageAlt(alt: string | undefined): string {
  const label = (alt ?? '').replace(/[[\]]/g, '').trim()
  return label || DEFAULT_IMAGE_ALT
}

/** A nested media element as a link (the fallback of a media node inside a list item, quote or table cell). */
function mediaLink(node: PostMediaNode): string {
  const label = escapePostMd(node.name ?? node.msgType)
  return /^https?:\/\//i.test(node.ref.src) ? `[${label}](${escapeLinkHref(node.ref.src)})` : label
}

/** Render inline runs to markdown, resolving image references to their uploaded keys. */
function inlineText(inlines: readonly PostInline[], key: (ref: ResourceRef) => string): string {
  let out = ''
  for (const inline of inlines) {
    out += inline.kind === 'inline-image' ? `![${imageAlt(inline.alt)}](${key(inline.ref)})` : inline.text
  }
  return out
}

/**
 * Wrap inline runs in a marker pair (`**`, `*`, `~~`, `<u>`), moving the whitespace of the boundary runs outside the
 * markers: CommonMark refuses to open emphasis before a space, so `** bold **` would stay literal otherwise.
 */
function wrapRuns(open: string, close: string, inlines: readonly PostInline[]): PostInline[] {
  const runs = [...inlines]
  let leading = ''
  const first = runs[0]
  if (first && (first.kind === 'text' || first.kind === 'raw')) {
    const match = /^\s+/.exec(first.text)
    if (match) {
      leading = match[0]
      runs[0] = { ...first, text: first.text.slice(leading.length) }
    }
  }
  let trailing = ''
  const last = runs[runs.length - 1]
  if (last && (last.kind === 'text' || last.kind === 'raw')) {
    const match = /\s+$/.exec(last.text)
    if (match) {
      trailing = match[0]
      runs[runs.length - 1] = { ...last, text: last.text.slice(0, last.text.length - trailing.length) }
    }
  }
  const empty = runs.every(run => (run.kind === 'text' || run.kind === 'raw') && !run.text)
  if (empty) return [...inlines]
  return [
    ...leading ? [raw(leading)] : [],
    raw(open),
    ...runs,
    raw(close),
    ...trailing ? [raw(trailing)] : [],
  ]
}

/** Wrap the rendered children of an inline element ({@link wrapRuns} on its inline runs). */
function wrapChildren(open: string, close: string, ctx: RenderContext<PostTypes>, el: Element): PostInline[] {
  const inlines = inlinesOf(ctx.render(el.children))
  return inlines.length ? wrapRuns(open, close, inlines) : []
}

// ---------------------------------------------------------------------------------------------------------------
// Block handlers

const HEADING_LEVELS = { h1: 1, h2: 2, h3: 3, h4: 4, h5: 5, h6: 6 } as const

function headingNode(level: number, ctx: RenderContext<PostTypes>, el: Element): PostMdNode {
  return { kind: 'md', lines: [{ prefix: `${'#'.repeat(level)} `, inlines: inlinesOf(ctx.render(el.children)) }] }
}

function extOf(value: string | undefined): string | undefined {
  return /\.([a-z0-9]+)(?:[?#].*)?$/i.exec(value ?? '')?.[1]?.toLowerCase()
}

/** Add the marker to the first content line of a list item and indent its continuation lines. */
function markItem(item: PostLiNode, indent: string, marker: string): PostLine[] {
  const lines = item.lines.map(cloneLine)
  if (!lines.length) return [{ prefix: `${indent}${marker.trimEnd()}`, inlines: [] }]
  const target = lines.findIndex(line => !line.prefix)
  if (target < 0) lines.unshift({ prefix: `${indent}${marker.trimEnd()}`, inlines: [] })
  else lines[target] = { prefix: `${indent}${marker}`, inlines: lines[target]!.inlines }
  const continuation = ' '.repeat(indent.length + marker.length)
  for (let index = 0; index < lines.length; index++) {
    const line = lines[index]!
    if (!line.prefix) lines[index] = { prefix: continuation, inlines: line.inlines }
  }
  return lines
}

function listNode(el: Element<'ul' | 'ol'>, ctx: RenderContext<PostTypes>, ordered: boolean): PostMdNode {
  // Nested lists are indented by their depth; `ctx.ancestors` is the only place that knows it.
  const depth = ctx.ancestors.filter(item => item.type === 'ul' || item.type === 'ol').length
  const indent = '  '.repeat(depth)
  const items = ctx.render(el.children).filter((node): node is PostLiNode => node.kind === 'li')
  const start = ordered ? (el as Element<'ol'>).attrs.start : undefined
  let number = typeof start === 'number' ? start : 1
  const lines: PostLine[] = []
  for (const item of items) {
    const bullet = ordered ? `${number++}. ` : '- '
    const marker = typeof item.checked === 'boolean' ? `${bullet}${item.checked ? '[x]' : '[ ]'} ` : bullet
    lines.push(...markItem(item, indent, marker))
  }
  return { kind: 'md', lines }
}

/** The md token a `<br>` produces (a backslash at the end of a line: a hard break in CommonMark). */
const HARD_BREAK = '\\\n'

/** One line of quoted content, `> ` prefixed. A hard break splits it into physical lines so every one stays quoted. */
function quoteLine(line: PostLine): PostLine[] {
  const head = line.prefix || line.inlines.length ? `> ${line.prefix}` : '>'
  if (!line.inlines.length) return [{ prefix: head, inlines: [] }]
  const segments: PostInline[][] = [[]]
  for (const inline of line.inlines) {
    if (inline.kind === 'raw' && inline.text === HARD_BREAK) {
      // The physical line ends with a backslash (the join adds the newline) and the next one keeps the marker.
      segments[segments.length - 1]!.push(raw('\\'))
      segments.push([])
      continue
    }
    segments[segments.length - 1]!.push(inline)
  }
  return segments.filter(segment => segment.length).map(inlines => ({ prefix: head, inlines }))
}

/** A quote block: every line of every child block gets one more `> ` prefix; blocks are separated by a bare `>`. */
function quoteNode(children: readonly PostNode[]): PostMdNode {
  const lines: PostLine[] = []
  for (const child of children) {
    const childLines = child.kind === 'md' ? child.lines : [{ prefix: '', inlines: inlinesOf([child]) }]
    if (lines.length) lines.push({ prefix: '>', inlines: [] })
    for (const line of childLines) lines.push(...quoteLine(line))
  }
  return { kind: 'md', lines }
}

function cellText(cell: PostCellNode | undefined): string {
  if (!cell) return ''
  // A hard break or a block inside a cell would end the table row, so its content is flattened to one line.
  return inlineLabel(cell.inlines)
    .replace(/\\\n/g, ' ')
    .replace(/\s*\n\s*/g, ' ')
    .replace(/(?<!\\)\|/g, '\\|')
    .trim()
}

function tableNode(children: readonly PostNode[]): PostMdNode {
  const rows = children.filter((node): node is PostRowNode => node.kind === 'row')
  const columns = Math.max(1, ...rows.map(row => row.cells.length))
  const rowLine = (row: PostRowNode | undefined): string => {
    const cells: string[] = []
    for (let column = 0; column < columns; column++) cells.push(cellText(row?.cells[column]))
    return `| ${cells.join(' | ')} |`
  }
  const aligns: (Align | undefined)[] = []
  for (let column = 0; column < columns; column++) {
    aligns.push(rows.map(row => row.cells[column]?.align).find(align => align !== undefined && align !== 'left'))
  }
  const separator = `| ${aligns.map(align => align === 'right' ? '---:' : align === 'center' ? ':---:' : '---').join(' | ')} |`
  return {
    kind: 'md',
    lines: [
      { prefix: '', inlines: [raw(rowLine(rows[0]))] },
      { prefix: '', inlines: [raw(separator)] },
      ...rows.slice(1).map(row => ({ prefix: '', inlines: [raw(rowLine(row))] })),
    ],
  }
}

function cellNode(el: Element<'th' | 'td'>, ctx: RenderContext<PostTypes>, header: boolean): PostCellNode {
  return {
    kind: 'cell',
    header,
    ...el.attrs.align ? { align: el.attrs.align } : {},
    inlines: inlinesOf(ctx.render(el.children)),
  }
}

function mediaNode(
  kind: 'audio' | 'video' | 'file',
  el: Element<'audio' | 'video' | 'file'>,
  ctx: RenderContext<PostTypes>,
): PostMediaNode {
  const { src } = el.attrs
  const name = el.attrs.name
  const extension = extOf(name ?? src)
  let msgType: 'audio' | 'media' | 'file' = 'file'
  if (kind === 'audio' && extension === 'opus') msgType = 'audio'
  else if (kind === 'video' && extension === 'mp4') msgType = 'media'
  const path = ctx.stableId(el)
  if (kind !== 'file' && msgType === 'file') {
    ctx.report.moved.push({ tag: kind, reason: kind === 'audio' ? 'not-opus' : 'not-mp4', path })
  }
  return {
    kind: 'media',
    msgType,
    ref: ctx.resource(kind, src, { ...name ? { name } : {} }),
    ...name ? { name } : {},
    path,
  }
}

// ---------------------------------------------------------------------------------------------------------------
// Assemble

/**
 * Group the transformed nodes into platform messages:
 * - media elements become their own message in tree order, so the text before and after them ends up in separate
 *   post messages;
 * - an inline image is hoisted into its own paragraph (`img` must be the sole node of a paragraph) and reported;
 * - `<title>` becomes the post `title`; its subtitle has no slot in a post, so it becomes the first body paragraph.
 */
function assemble(
  nodes: readonly PostNode[],
  envelope: Envelope,
  ctx: RenderContext<PostTypes>,
): PostDraft[] {
  const drafts: PostDraft[] = []
  let paragraphs: PostParagraph[] = []
  const flush = () => {
    if (!paragraphs.length) return
    drafts.push({ kind: 'post', paragraphs })
    paragraphs = []
  }

  for (const node of nodes) {
    if (node.kind === 'media') {
      flush()
      drafts.push({ kind: 'media', msgType: node.msgType, ref: node.ref, ...node.name ? { name: node.name } : {} })
      continue
    }
    if (node.kind === 'image' || node.kind === 'hr') {
      paragraphs.push(node)
      continue
    }
    const lines = node.kind === 'md' ? node.lines : [{ prefix: '', inlines: inlinesOf([node]) }]
    let current: PostMdNode | undefined
    for (const line of lines) {
      const open = (): PostMdNode => {
        if (!current) {
          current = { kind: 'md', lines: [] }
          paragraphs.push(current)
        }
        return current
      }
      if (!line.inlines.length) {
        // Keep the prefix: an empty line inside a quote is a bare `>`, not a paragraph break.
        open().lines.push({ prefix: line.prefix, inlines: [] })
        continue
      }
      let inlines: PostInline[] = []
      const flushInlines = () => {
        if (!inlines.length) return
        open().lines.push({ prefix: line.prefix, inlines })
        inlines = []
      }
      for (const inline of line.inlines) {
        if (inline.kind !== 'inline-image') {
          inlines.push(inline)
          continue
        }
        flushInlines()
        paragraphs.push({ kind: 'image', ref: inline.ref, ...inline.alt ? { alt: inline.alt } : {} })
        if (inline.path) ctx.report.moved.push({ tag: 'img', reason: 'own-paragraph', path: inline.path })
        // The text after the image starts a new md node, so the image stays on a paragraph of its own.
        current = undefined
      }
      flushInlines()
    }
  }
  flush()

  const title = envelope.title
  if (title) {
    const value = ctx.text(title.children).trim()
    const subtitle = title.attrs.subtitle?.trim()
    let target = drafts.find((draft): draft is PostTextDraft => draft.kind === 'post')
    if (!target) {
      target = { kind: 'post', paragraphs: [] }
      drafts.unshift(target)
    }
    if (value) target.title = value
    if (subtitle) {
      target.paragraphs.unshift({ kind: 'md', lines: [{ prefix: '', inlines: [raw(`*${escapePostMd(subtitle)}*`)] }] })
      ctx.report.moved.push({ tag: 'title', reason: 'subtitle-paragraph', path: ctx.stableId(title) })
    }
  }

  if (!drafts.length) drafts.push({ kind: 'post', paragraphs: [{ kind: 'md', lines: [blankLine()] }] })
  if (drafts.length > 1) ctx.report.split += drafts.length - 1
  return drafts
}

// ---------------------------------------------------------------------------------------------------------------
// Serialize

function paragraphNodes(paragraph: PostParagraph, key: (ref: ResourceRef) => string): Record<string, unknown>[] {
  switch (paragraph.kind) {
    case 'md': return [{
      tag: 'md',
      text: paragraph.lines.map(line => `${line.prefix}${inlineText(line.inlines, key)}`).join('\n'),
    }]
    case 'image': return [{ tag: 'img', image_key: key(paragraph.ref) }]
    case 'hr': return [{ tag: 'hr' }]
  }
}

/** The exact `content` object of one draft (also used by `check`, with placeholder resource keys). */
function contentOf(draft: PostDraft, locale: string, key: (ref: ResourceRef) => string): PostPayload {
  if (draft.kind === 'media') {
    return { msg_type: draft.msgType, content: { file_key: key(draft.ref) } }
  }
  const body: Record<string, unknown> = {}
  if (draft.title) body.title = draft.title
  body.content = draft.paragraphs.length
    ? draft.paragraphs.map(paragraph => paragraphNodes(paragraph, key))
    : [[{ tag: 'md', text: '' }]]
  return { msg_type: 'post', content: { [locale]: body } }
}

/** Bytes of the JSON-encoded platform content — the part of the request `limit.payload.bytes` bounds. */
function contentBytes(payload: PostPayload): number {
  return new TextEncoder().encode(JSON.stringify(payload.content)).length
}

// ---------------------------------------------------------------------------------------------------------------
// Mode

/**
 * Create the Lark post mode. Pure: the config only shapes the element table (and the body locale), so one
 * adapter can build one mode per configuration and `LarkBot.createModes()` can call this directly.
 */
export function createPostMode(config: PostModeConfig = {}): Mode<PostTypes> {
  const locale = config.locale ?? 'zh_cn'
  const payloadLimit = config.payloadBytes ?? POST_PAYLOAD_BYTES
  const updateLimit = config.updateLimit ?? POST_UPDATE_LIMIT

  const elements = new ElementRegistry<PostTypes>()
    .register('text', el => text(el.attrs.content))
    // A hard break: a backslash at the end of a line, which CommonMark turns into a `<br>`.
    .register('br', () => raw(HARD_BREAK))
    .register('p', (el, ctx) => ({
      kind: 'md',
      lines: [{ prefix: '', inlines: inlinesOf(ctx.render(el.children)) }],
    }))
    // A root `<title>` becomes the post title through `assemble`, which is why the mode declares the envelope tag.
    .envelope('title')
    .register('b', (el, ctx) => wrapChildren('**', '**', ctx, el))
    .register('i', (el, ctx) => wrapChildren('*', '*', ctx, el))
    .register('s', (el, ctx) => wrapChildren('~~', '~~', ctx, el))
    // A post `md` node renders `<u>…</u>` (2026-11-11, a real message), while the card markdown dialect has no
    // underline and shows the tag itself — which is what sends underlined content to this mode.
    .register('u', (el, ctx) => wrapChildren('<u>', '</u>', ctx, el))
    .register('code', (el, ctx) => raw(codeSpan(ctx.text(el.children))))
    .register('a', (el, ctx) => {
      const href = el.attrs.href?.trim()
      const inlines = inlinesOf(ctx.render(el.children))
      const label = inlineLabel(inlines)
      if (!href) return inlines
      // A bare URL is autolinked by the platform, so an anchor whose label is the URL stays readable.
      if (!label || label === href) return raw(escapeLinkHref(href))
      return raw(`[${label}](${escapeLinkHref(href)})`)
    })
    .register('at', el => raw(mentionMarkdown('post', el.attrs)), {
      variants: config.allowAtAll === false ? ['user'] : ['user', 'all'],
    })
    .register('h1', (el, ctx) => headingNode(HEADING_LEVELS.h1, ctx, el))
    .register('h2', (el, ctx) => headingNode(HEADING_LEVELS.h2, ctx, el))
    .register('h3', (el, ctx) => headingNode(HEADING_LEVELS.h3, ctx, el))
    .register('h4', (el, ctx) => headingNode(HEADING_LEVELS.h4, ctx, el))
    .register('h5', (el, ctx) => headingNode(HEADING_LEVELS.h5, ctx, el))
    .register('h6', (el, ctx) => headingNode(HEADING_LEVELS.h6, ctx, el))
    .register('ul', (el, ctx) => listNode(el, ctx, false))
    .register('ol', (el, ctx) => listNode(el, ctx, true))
    .register('li', (el, ctx) => {
      const lines: PostLine[] = []
      for (const node of ctx.render(el.children)) {
        // A list item's blocks share the item's paragraph: a blank line would end the list, and a nested list
        // already carries its own indented lines.
        if (node.kind === 'md') lines.push(...node.lines.map(cloneLine))
        else lines.push({ prefix: '', inlines: inlinesOf([node]) })
      }
      return { kind: 'li', lines, ...typeof el.attrs.checked === 'boolean' ? { checked: el.attrs.checked } : {} }
    }, { variants: ['checked', 'nested'] })
    .register('blockquote', (el, ctx) => quoteNode(ctx.render(el.children)))
    .register('pre', (el, ctx) => {
      const lang = el.attrs.lang?.trim()
      return {
        kind: 'md',
        lines: [{ prefix: '', inlines: [raw(fenceBlock(ctx.text(el.children), lang || undefined))] }],
      }
    }, { variants: ['lang'] })
    .register('hr', () => ({ kind: 'hr' }))
    .register('table', (el, ctx) => tableNode(ctx.render(el.children)), { variants: ['align'] })
    .register('tr', (el, ctx) => ({
      kind: 'row',
      cells: ctx.render(el.children).filter((node): node is PostCellNode => node.kind === 'cell'),
    }))
    .register('th', (el, ctx) => cellNode(el, ctx, true))
    .register('td', (el, ctx) => cellNode(el, ctx, false))
    .register('img', (el, ctx) => ({
      kind: 'image',
      ref: ctx.resource('image', el.attrs.src, {
        ...el.attrs.width !== undefined ? { width: el.attrs.width } : {},
        ...el.attrs.height !== undefined ? { height: el.attrs.height } : {},
      }),
      ...el.attrs.alt ? { alt: el.attrs.alt } : {},
      path: ctx.stableId(el),
    }), { variants: ['inline'] })
    .register('audio', (el, ctx) => mediaNode('audio', el, ctx))
    .register('video', (el, ctx) => mediaNode('video', el, ctx))
    .register('file', (el, ctx) => mediaNode('file', el, ctx))

  return defineMode<PostTypes>()({
    id: 'post',
    elements,
    limits: { 'limit.payload.bytes': payloadLimit, 'limit.update.count': updateLimit },
    // A post divider is a real `<hr>` (`hr` line), so losing it is not an option: content with one is published in a
    // mode that can keep it, never here.
    degradation: { forbidden: ['hr'] },
    assemble,
    serialize: (msg: Prepared<PostDraft>, _ctx: SerializeContext) => contentOf(msg.draft, locale, ref => msg.resolved.get(ref)?.key ?? ''),
    check: (draft) => {
      // The draft is pre-resolution, so image keys are placeholders: a realistic key is ~40 bytes, which keeps the
      // check honest without depending on an upload.
      const actual = contentBytes(contentOf(draft, locale, () => 'img_v2_placeholder_key_0000000000'))
      if (actual <= payloadLimit) return []
      const violation: LimitViolation = {
        kind: 'size',
        key: 'limit.payload.bytes',
        limit: payloadLimit,
        actual,
        message: `the post body is ${actual} bytes and the platform accepts ${payloadLimit}`,
      }
      return [violation]
    },
  })
}
